          <option value="">Lead…</option>
          {(people.data ?? []).map((person) => (
            <option key={person.id} value={String(person.id)}>{person.name}</option>
          ))}
        </select>{' '}
        <button type="submit" data-testid="crew-form-submit" disabled={save.isPending}>
